import React, { useEffect, useMemo, useState } from 'react';
import api from '../../services/api';

const DEFAULT_FILTERS = {
  empresa_id: '',
  proveedor_id: '',
  lote: '',
  semaforo: ''
};

function formatNumber(value, decimals = 2) {
  if (value === null || value === undefined || value === '') return '-';
  const n = Number(value);
  if (Number.isNaN(n)) return '-';
  return n.toLocaleString('es-MX', { minimumFractionDigits: decimals, maximumFractionDigits: decimals });
}

function semaforoClass(semaforo) {
  const s = String(semaforo || '').toUpperCase();
  if (s === 'ROJO') return 'bg-red-100 text-red-700 border-red-200';
  if (s === 'AMARILLO') return 'bg-yellow-100 text-yellow-700 border-yellow-200';
  if (s === 'VERDE') return 'bg-green-100 text-green-700 border-green-200';
  return 'bg-gray-100 text-gray-700 border-gray-200';
}

export default function LotesProveedorPage() {
  const [filters, setFilters] = useState(DEFAULT_FILTERS);
  const [rendimientos, setRendimientos] = useState([]);
  const [total, setTotal] = useState(0);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [selected, setSelected] = useState(null);
  const [drilldown, setDrilldown] = useState(null);
  const [reclamos, setReclamos] = useState([]);
  const [modalReclamo, setModalReclamo] = useState(false);
  const [reclamoForm, setReclamoForm] = useState({ motivo: '', descripcion: '', prioridad: 'MEDIA' });

  const query = useMemo(() => {
    const params = new URLSearchParams();
    Object.entries(filters).forEach(([key, value]) => {
      if (value) params.append(key, value);
    });
    params.append('limit', '100');
    params.append('offset', '0');
    return params.toString();
  }, [filters]);

  async function loadData() {
    setLoading(true);
    setError('');
    try {
      const [rendimientosRes, reclamosRes] = await Promise.all([
        api.get(`/tablajeria/lotes-proveedor/rendimientos?${query}`),
        api.get('/tablajeria/reclamos-proveedor?limit=100')
      ]);
      setRendimientos(rendimientosRes.data?.rendimientos || []);
      setTotal(rendimientosRes.data?.total || 0);
      setReclamos(reclamosRes.data?.reclamos || []);
    } catch (err) {
      setError(err?.response?.data?.detail || 'No fue posible cargar lotes proveedor.');
    } finally {
      setLoading(false);
    }
  }

  async function openDrilldown(row) {
    setSelected(row);
    setDrilldown(null);
    try {
      const id = row.LoteRendimientoID || row.loteRendimientoID || row.lote_rendimiento_id;
      const res = await api.get(`/tablajeria/lotes-proveedor/${id}/drilldown`);
      setDrilldown(res.data);
    } catch (err) {
      setError(err?.response?.data?.detail || 'No fue posible cargar drilldown del lote.');
    }
  }

  async function crearReclamo() {
    if (!selected) return;
    const id = selected.LoteRendimientoID || selected.loteRendimientoID || selected.lote_rendimiento_id;
    try {
      await api.post(`/tablajeria/lotes-proveedor/${id}/reclamos`, {
        motivo: reclamoForm.motivo,
        descripcion: reclamoForm.descripcion,
        prioridad: reclamoForm.prioridad,
        evidencia: { origen: 'frontend_tablajeria_lotes_proveedor' }
      });
      setModalReclamo(false);
      setReclamoForm({ motivo: '', descripcion: '', prioridad: 'MEDIA' });
      await loadData();
      await openDrilldown(selected);
    } catch (err) {
      setError(err?.response?.data?.detail || 'No fue posible abrir reclamo proveedor.');
    }
  }

  useEffect(() => {
    loadData();
  }, [query]);

  return (
    <div className="p-6 space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-semibold text-gray-900">Lotes proveedor y reclamos</h1>
          <p className="text-sm text-gray-500">Rendimiento de tablajería por lote de compra, proveedor, semáforo e impacto económico.</p>
        </div>
        <button onClick={loadData} className="px-4 py-2 rounded bg-gray-900 text-white text-sm">Actualizar</button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-4 gap-3 bg-white p-4 rounded-lg border">
        <input className="border rounded px-3 py-2 text-sm" placeholder="Empresa ID" value={filters.empresa_id} onChange={(e) => setFilters({ ...filters, empresa_id: e.target.value })} />
        <input className="border rounded px-3 py-2 text-sm" placeholder="Proveedor ID" value={filters.proveedor_id} onChange={(e) => setFilters({ ...filters, proveedor_id: e.target.value })} />
        <input className="border rounded px-3 py-2 text-sm" placeholder="Lote proveedor / interno" value={filters.lote} onChange={(e) => setFilters({ ...filters, lote: e.target.value })} />
        <select className="border rounded px-3 py-2 text-sm" value={filters.semaforo} onChange={(e) => setFilters({ ...filters, semaforo: e.target.value })}>
          <option value="">Todos los semáforos</option>
          <option value="VERDE">Verde</option>
          <option value="AMARILLO">Amarillo</option>
          <option value="ROJO">Rojo</option>
        </select>
      </div>

      {error && <div className="bg-red-50 border border-red-200 text-red-700 px-4 py-3 rounded">{error}</div>}

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <div className="lg:col-span-2 bg-white rounded-lg border overflow-hidden">
          <div className="px-4 py-3 border-b flex justify-between text-sm">
            <span className="font-medium">Rendimientos por lote</span>
            <span className="text-gray-500">{loading ? 'Cargando...' : `${total} registros`}</span>
          </div>
          <div className="overflow-x-auto">
            <table className="min-w-full text-sm">
              <thead className="bg-gray-50 text-gray-600">
                <tr>
                  <th className="text-left p-3">Lote</th>
                  <th className="text-left p-3">Proveedor</th>
                  <th className="text-left p-3">Orden</th>
                  <th className="text-right p-3">Rend. real</th>
                  <th className="text-right p-3">Desv.</th>
                  <th className="text-right p-3">Impacto</th>
                  <th className="text-center p-3">Semáforo</th>
                </tr>
              </thead>
              <tbody>
                {rendimientos.map((row) => (
                  <tr key={row.LoteRendimientoID} className="border-t hover:bg-gray-50 cursor-pointer" onClick={() => openDrilldown(row)}>
                    <td className="p-3">
                      <div className="font-medium">{row.LoteProveedor || '-'}</div>
                      <div className="text-xs text-gray-500">{row.LoteInterno || '-'}</div>
                    </td>
                    <td className="p-3">{row.ProveedorNombre || '-'}</td>
                    <td className="p-3">{row.FolioOrdenTablaje || '-'}</td>
                    <td className="p-3 text-right">{formatNumber(row.RendimientoRealPorcentaje)}%</td>
                    <td className="p-3 text-right">{formatNumber(row.DesviacionPorcentaje)}%</td>
                    <td className="p-3 text-right">${formatNumber(row.ImpactoEconomico)}</td>
                    <td className="p-3 text-center"><span className={`px-2 py-1 rounded border text-xs ${semaforoClass(row.Semaforo)}`}>{row.Semaforo || 'SIN_DATOS'}</span></td>
                  </tr>
                ))}
                {!rendimientos.length && !loading && (
                  <tr><td className="p-6 text-center text-gray-500" colSpan="7">Sin registros de lote proveedor.</td></tr>
                )}
              </tbody>
            </table>
          </div>
        </div>

        <div className="bg-white rounded-lg border p-4 space-y-4">
          <div className="flex justify-between items-center">
            <h2 className="font-medium">Drilldown</h2>
            {selected && <button onClick={() => setModalReclamo(true)} className="px-3 py-1 rounded bg-orange-600 text-white text-xs">Abrir reclamo</button>}
          </div>
          {!selected && <p className="text-sm text-gray-500">Selecciona un lote para ver compra, recepción, tablajería, reclamos y notificaciones.</p>}
          {selected && (
            <div className="text-sm space-y-3">
              <div>
                <div className="text-xs text-gray-500">Proveedor</div>
                <div className="font-medium">{selected.ProveedorNombre || '-'}</div>
              </div>
              <div className="grid grid-cols-2 gap-3">
                <div><div className="text-xs text-gray-500">OC</div><div>{selected.OrdenCompraFolio || '-'}</div></div>
                <div><div className="text-xs text-gray-500">Recepción</div><div>{selected.RecepcionFolio || '-'}</div></div>
                <div><div className="text-xs text-gray-500">Factura</div><div>{selected.FacturaFolio || '-'}</div></div>
                <div><div className="text-xs text-gray-500">Fecha</div><div>{selected.FechaOperacionMexico || '-'}</div></div>
              </div>
              <div className="border-t pt-3">
                <div className="font-medium mb-2">Reclamos</div>
                {(drilldown?.reclamos || []).map((r) => (
                  <div key={r.ReclamoProveedorID} className="border rounded p-2 mb-2">
                    <div className="font-medium">{r.FolioReclamo}</div>
                    <div className="text-xs text-gray-500">{r.Estatus} · {r.Prioridad}</div>
                    <div>{r.Motivo}</div>
                  </div>
                ))}
                {drilldown && !drilldown.reclamos?.length && <div className="text-gray-500">Sin reclamos.</div>}
              </div>
              <div className="border-t pt-3">
                <div className="font-medium mb-2">Notificaciones</div>
                {(drilldown?.notificaciones || []).map((n) => (
                  <div key={n.NotificacionLoteID} className="text-xs border rounded p-2 mb-2">
                    {n.Canal} · {n.Destinatario} · {n.EstatusEnvio}
                  </div>
                ))}
                {drilldown && !drilldown.notificaciones?.length && <div className="text-gray-500">Sin notificaciones.</div>}
              </div>
            </div>
          )}
        </div>
      </div>

      <div className="bg-white rounded-lg border overflow-hidden">
        <div className="px-4 py-3 border-b font-medium">Reclamos proveedor abiertos / históricos</div>
        <table className="min-w-full text-sm">
          <thead className="bg-gray-50 text-gray-600">
            <tr>
              <th className="text-left p-3">Folio</th>
              <th className="text-left p-3">Proveedor</th>
              <th className="text-left p-3">Motivo</th>
              <th className="text-left p-3">Estatus</th>
              <th className="text-right p-3">Impacto</th>
            </tr>
          </thead>
          <tbody>
            {reclamos.map((r) => (
              <tr key={r.ReclamoProveedorID} className="border-t">
                <td className="p-3 font-medium">{r.FolioReclamo}</td>
                <td className="p-3">{r.ProveedorNombre || '-'}</td>
                <td className="p-3">{r.Motivo}</td>
                <td className="p-3">{r.Estatus}</td>
                <td className="p-3 text-right">${formatNumber(r.ImpactoEconomico)}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {modalReclamo && (
        <div className="fixed inset-0 bg-black bg-opacity-40 flex items-center justify-center z-50">
          <div className="bg-white rounded-lg p-5 w-full max-w-lg space-y-4">
            <h2 className="text-lg font-semibold">Abrir reclamo proveedor</h2>
            <input className="w-full border rounded px-3 py-2" placeholder="Motivo" value={reclamoForm.motivo} onChange={(e) => setReclamoForm({ ...reclamoForm, motivo: e.target.value })} />
            <textarea className="w-full border rounded px-3 py-2" rows="4" placeholder="Descripción" value={reclamoForm.descripcion} onChange={(e) => setReclamoForm({ ...reclamoForm, descripcion: e.target.value })} />
            <select className="w-full border rounded px-3 py-2" value={reclamoForm.prioridad} onChange={(e) => setReclamoForm({ ...reclamoForm, prioridad: e.target.value })}>
              <option value="BAJA">Baja</option>
              <option value="MEDIA">Media</option>
              <option value="ALTA">Alta</option>
              <option value="CRITICA">Crítica</option>
            </select>
            <div className="flex justify-end gap-2">
              <button className="px-4 py-2 rounded border" onClick={() => setModalReclamo(false)}>Cancelar</button>
              <button className="px-4 py-2 rounded bg-orange-600 text-white disabled:opacity-50" disabled={!reclamoForm.motivo} onClick={crearReclamo}>Crear reclamo</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

